:transparent;width:100%;min-width:0;color:var(--sf-ink)}.sf-header-actions{display:flex;align-items:center;gap:9px}.sf-icon-btn,.sf-cart-btn,.sf-menu-btn{border:1px solid var(--sf-line);background:var(--sf-surface);color:var(--sf-ink);border-radius:999px;min-height:42px;padding:0 15px;font-weight:800;font-size:12px}.sf-cart-btn{background:var(--sf-primary);border-color:var(--sf-primary);color:#fff}.sf-cart-count{display:inline-grid;place-items:center;min-width:21px;height:21px;margin-left:6px;padding:0 5px;border-radius:99px;background:rgba(255,255,255,.22)}.sf-menu-btn{display:none}.sf-nav{max-width:1320px;margin:auto;padding:0 4vw 12px;display:flex;gap:7px;align-items:center;overflow:auto;scrollbar-width:none}.sf-nav a{white-space:nowrap;padding:7px 12px;border-radius:99px;color:var(--sf-muted);font-size:12px;font-weight:800}.sf-nav a:hover,.sf-nav a[aria-current=page]{background:var(--sf-primary);color:#fff}.sf-main{max-width:1320px;margin:auto;padding:30px 4vw 80px}.sf-page-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin:10px 0 26px}.sf-kicker{font-size:10px;font-weight:900;letter-spacing:.16em;text-transform:uppercase;color:var(--sf-primary)}.sf-page-head h1{margin:7px 0 6px;font-family:var(--sf-display);font-size:clamp(30px,5vw,54px);line-height:1.02;letter-spacing:-.05em}.sf-page-head p{max-width:680px;margin:0;color:var(--sf-muted)}.sf-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 19px;border:0;border-radius:999px;background:var(--sf-primary);color:#fff;font-weight:900;font-size:13px;transition:transform .2s,box-shadow .2s}.sf-btn:hover{transform:translateY(-2px);box-shadow:0 9px 22px color-mix(in srgb,var(--sf-primary) 22%,transparent)}.sf-btn.secondary{background:var(--sf-surface);border:1px solid var(--sf-line);color:var(--sf-ink)}.sf-btn:disabled{opacity:.45;cursor:not-allowed;transform:none;box-shadow:none}.sf-hero{position:relative;isolation:isolate;display:grid;grid-