/* Healthcare editorial image distribution: page-level imagery, never a photo-wall. */
.sf-health-card{overflow:hidden;padding:0;text-decoration:none;color:inherit}
.sf-health-card-image{display:block;width:100%;height:170px;object-fit:cover;border-radius:10px 10px 0 0;pointer-events:none}
.sf-health-card>small,.sf-health-card>h3,.sf-health-card>p,.sf-health-card>b{display:block;margin-left:18px;margin-right:18px}
.sf-health-card>small{margin-top:16px}
.sf-health-card>b{margin-bottom:18px}
.sf-health-media-section{max-width:1120px;margin:34px auto 58px;padding:0 22px}
.sf-health-media-heading{margin:0 0 22px}
