.sf-re-hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,1.05fr);gap:clamp(28px,5vw,76px);align-items:center;max-width:1440px;margin:0 auto;padding:clamp(24px,4vw,56px) 0 34px}
.sf-re-hero-copy>small,.sf-re-section small,.sf-re-services small,.sf-re-cta small{display:block;color:var(--re-accent);font-size:10px;font-weight:800;letter-spacing:.19em;text-transform:uppercase}
.sf-re-hero h1{font-family:Georgia,serif;font-size:clamp(42px,6vw,82px);line-height:1.02;font-weight:500;max-width:720px;margin:18px 0}
.sf-re-hero-copy>p{font-size:clamp(15px,1.5vw,18px);line-height:1.8;color:#68747a;max-width:560px}
