.sf-re-search input,.sf-re-search select,.sf-re-listing-tools input,.sf-re-listing-tools select,.sf-re-enquiry-form input,.sf-re-enquiry-form select,.sf-re-enquiry-form textarea{width:100%;min-height:46px;padding:12px 14px;border:1px solid var(--re-line);border-radius:2px;background:#fff;color:var(--re-ink);font:inherit}
.sf-realestate .sf-btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:13px 20px;border:0;border-radius:2px;background:var(--re-ink);color:#fff;font-size:12px;font-weight:800;letter-spacing:.02em}
