.sf-re-section,.sf-re-services,.sf-re-cta{max-width:1440px;margin:0 auto 64px}
.sf-re-section-head{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:24px}
.sf-re-section-head h2,.sf-re-services h2,.sf-re-cta h2{font-family:Georgia,serif;font-size:clamp(30px,4vw,52px);font-weight:500;margin:10px 0}
